kIn = input(7, "K Neighbors", 1, 20, 1)
featLen = input(20, "Feature Length", 5, 40, 1)
histWin = input(200, "History Window", 50, 500, 10)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disThresh = input(0.5, "Disagreement Threshold", 0.1, 0.9, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── 1-bar return from bar data (audited: guarded divide, NaN-free warmup) ───
denom = close[1]
retNow = 0.0
if bar_index == 0 {
    retNow := 0.0
}
if bar_index > 0 {
    retNow := (close - close[1]) / (denom + 0.000000001)
}

// realized direction label of this bar vs prior close: +1 up, -1 down/flat
dirNow = -1
if bar_index == 0 {
    dirNow := 1
}
if bar_index > 0 {
    if close > close[1] {
        dirNow := 1
    }
}

// ─── Persistent return + label history (grows every bar, never frozen) ───
varip retHist = array(0)
varip dirHist = array(0)
array.push(retHist, retNow)
array.push(dirHist, dirNow)

// ─── KNN search over last featLen returns vs History Window ───
voteMargin = 0.0
disN = 0.0
meanD = 0.0
upCount = 0
downCount = 0

nBars = array.size(retHist)
enough = nBars > featLen + 12

if enough {
    curStart = nBars - featLen
    endI = nBars - featLen - 1
    startI = endI - histWin
    if startI < 0 {
        startI := 0
    }

    // k-slot insertion buffers for smallest distances + their labels
    bestDist = array(0)
    bestLab = array(0)
    q = 0
    while q < kIn {
        array.push(bestDist, 999999.0)
        array.push(bestLab, 0)
        q := q + 1
    }

    ii = startI
    while ii <= endI {
        ssd = 0.0
        j = 0
        while j < featLen {
            a = retHist[curStart + j]
            b = retHist[ii + j]
            d = a - b
            ssd := ssd + d * d
            j := j + 1
        }
        dist = sqrt(ssd)

        labIdx = ii + featLen
        lab = -1
        if labIdx < nBars {
            if dirHist[labIdx] == 1 {
                lab := 1
            }
        }

        // ordered insert into k smallest
        insIdx = -1
        m = 0
        while m < kIn {
            if dist < bestDist[m] {
                insIdx := m
                m := kIn
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = kIn - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestLab, insIdx, lab)
        }
        ii := ii + 1
    }

    // Channel 1: vote margin from neighbour labels
    up = 0
    dn = 0
    valid = 0
    m = 0
    while m < kIn {
        if bestDist[m] < 999998.0 {
            valid := valid + 1
            if bestLab[m] == 1 {
                up := up + 1
            } else {
                dn := dn + 1
            }
        }
        m := m + 1
    }
    if valid > 0 {
        voteMargin := (up - dn) / valid
        upCount := up
        downCount := dn
    }

    // Channel 2: neighbour disagreement from neighbour DISTANCES only
    if valid > 0 {
        s = 0.0
        m = 0
        while m < valid {
            s := s + bestDist[m]
            m := m + 1
        }
        mu = s / valid
        meanD := mu
        v = 0.0
        m = 0
        while m < valid {
            e = bestDist[m] - mu
            v := v + e * e
            m := m + 1
        }
        sd = sqrt(v / valid)
        dis = sd / (mu + 0.0000000001)
        disN := dis / (1.0 + dis)
    }
}

// ─── Signal rules: both channels must agree + edge on prior no-signal ───
rawBuy = voteMargin > marginThresh and disN < disThresh and enough
rawSell = voteMargin < 0 - marginThresh and disN < disThresh and enough
prevRawBuy = rawBuy[1]
prevRawSell = rawSell[1]
prevNoSig = not prevRawBuy and not prevRawSell
buySig = rawBuy and prevNoSig
sellSig = rawSell and prevNoSig

if buySig {
