// ─── 2D: two independently readable channels (separate pane) ───
plot(voteMargin * 100, "Vote Margin M", "#22cc88", 2, "separate")
plot(disN * 100, "Disagreement DisN", "#ff4477", 2, "separate")

// ─── 3D: crisp = tall margin surface + low disagreement bars; contested = flat + tall bars ───
plot3d(voteMargin * 100, "Margin Channel", "surface", "#22cc88", "separate", 0)
plot3d(disN * 100, "Disagreement Channel", "bars3d", "#ff4477", "separate", 1)

if buySig {
