// Session Value Profile Model
// Volume-profile-on-chart: POC + value area from visible session, breakout signals leaving value.

ProfileRows = input(24, "Profile Rows", 10, 48, 1)
ValueAreaPct = input(70, "Value Area %", 50, 90, 5)
SessionLength = input(100, "Session Length", 24, 300, 5)
ShowValueArea = input(true, "Show Value Area")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, SessionLength)
ll = lowest(low, SessionLength)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / ProfileRows
if rowH <= 0 {
    rowH := close * 0.0001
}

// ─── Build row volumes from last SessionLength bars ───
rv = array()
i = 0
while i < ProfileRows {
    array.push(rv, 0.0)
    i := i + 1
}
k = 0
while k < SessionLength {
    typ = (high[k] + low[k] + close[k]) / 3
    idx = floor((typ - ll) / rowH)
    if idx < 0 {
        idx := 0
    }
    if idx > ProfileRows - 1 {
        idx := ProfileRows - 1
    }
    oldv = array.get(rv, idx)
    array.set(rv, idx, oldv + volume[k])
    k := k + 1
}

// ─── POC: row with max volume ───
pocRow = 0
pocVol = array.get(rv, 0)
i = 1
while i < ProfileRows {
    v = array.get(rv, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
totalVol = array.sum(rv)
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVol / totalVol
}
pocPrice = ll + (pocRow + 0.5) * rowH

// ─── Value area: expand from POC adding larger adjacent row ───
vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * ValueAreaPct / 100
guard = 0
while accum < target and guard < ProfileRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(rv, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < ProfileRows - 1 {
        rightVal := array.get(rv, vaHigh + 1)
    }
    if rightVal < 0 and leftVal < 0 {
        guard := ProfileRows
    } else {
        if rightVal >= leftVal and vaHigh < ProfileRows - 1 {
            vaHigh := vaHigh + 1
            accum := accum + rightVal
        } else {
            if vaLow > 0 {
                vaLow := vaLow - 1
                accum := accum + leftVal
            } else {
                if vaHigh < ProfileRows - 1 {
                    vaHigh := vaHigh + 1
                    accum := accum + rightVal
                }
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) * rowH
valPrice = ll + vaLow * rowH
vaWidth = vahPrice - valPrice

// ─── Terrain ridge (price-denominated): POC lifted by concentration ───
ridgePrice = pocPrice + pocShare * rng * 0.5 + (close - pocPrice) * 0.02
vaMid = (vahPrice + valPrice) / 2

// ─── Signals: price leaving value ───
prevVah = vahPrice[1]
prevVal = valPrice[1]
prevClose = close[1]
wasInside = prevClose >= prevVal and prevClose <= prevVah
buySig = wasInside and close > vahPrice
sellSig = wasInside and close < valPrice

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "3d")
}

// ─── 2D: same information when 3D is off ───
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(ridgePrice, "Value Ridge", "#b48cff", 1)
if ShowValueArea {
    bgcolor("rgba(68,136,255,0.05)")
}

// ─── 3D: value terrain + POC labelled rail + VA edge rails ───
plot3d(ridgePrice, "Value Terrain", "surface", "#4488ff", "3d", 3)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 0, "3d")

